arduino.setup:
Serial.begin(9600);
pinMode(${D}, OUTPUT);
pinMode(${CLK}, OUTPUT);
pinMode(${Q}, INPUT);
pinMode(${Qbar}, INPUT);
Serial.println("D Flip-Flop ready");

arduino.loop:
for (int i=0; i<2; i++) {
  digitalWrite(${D}, i?HIGH:LOW);
  digitalWrite(${CLK}, LOW);
  delay(5);
  digitalWrite(${CLK}, HIGH);
  delay(5);
  Serial.print("DFF | D=");
  Serial.print(i);
  Serial.print(" -> Q=");
  Serial.print(digitalRead(${Q}));
  Serial.print(" Qbar=");
  Serial.println(digitalRead(${Qbar}));
  delay(1000);
}
